"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[9174],{496:e=>{e.exports=JSON.parse('{"tag":{"label":"AI Agents","permalink":"/datagol-knowlegde-base-v1/docs/tags/ai-agents","allTagsPath":"/datagol-knowlegde-base-v1/docs/tags","count":12,"items":[{"id":"AI Agents/About AI agents","title":"About AI agents","description":"The DataGOL AI agents empowers business users and engineers to efficiently analyze and visualize data through a suite of specialized AI agents. These agents act as intelligent assistants, guiding users through the data exploration process and accelerating insights.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/about-ai-agent"},{"id":"AI Agents/AI Search agent","title":"AI Search agent","description":"What is AI Search agent?","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/ai-search-agent"},{"id":"AI Agents/Business Intelligence (BI) agent - (Chart agent)","title":"Business Intelligence (BI) agent - (Chart agent)","description":"BI or Chart agent allows you to visualize data from structured datasets using various chart types and provides insights through graphical representations of data.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/business-intelligence-BI-agent-Chart-agent"},{"id":"AI Agents/Custom agent","title":"Custom agent","description":"What is Custom agent?","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/custom-agent"},{"id":"AI Agents/Data Cleaning (DC) agent","title":"Data Cleaning (DC) agent","description":"The DC agent helps users to clean and organize their data within a workbook. This includes tasks like deduplication, normalization, data imputation, and filtering.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/data-cleaning-agent-DCA-agent"},{"id":"AI Agents/Data Conversion agent (DCA)","title":"Data Conversion agent (DCA)","description":"The DCA enables users to quickly retrieve and analyze data from workbooks using natural language queries. Moreover, the agent also provides tabular results based on SQL queries.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/data-conversion-agent"},{"id":"AI Agents/HubSpot agent","title":"HubSpot agent","description":"The HubSpot agent is an AI-powered tool designed to interact with your HubSpot CRM. It allows you to retrieve information and perform actions directly within your HubSpot environment by using natural language commands.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/hubspot-agent"},{"id":"AI Agents/Jira agent","title":"Jira agent","description":"What is the Jira agent?","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/jira-agent"},{"id":"AI Agents/Python agent","title":"Python agent","description":"What is Python agent?","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/python-agent"},{"id":"AI Agents/RAG agent","title":"RAG agent","description":"What is a RAG agent?","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/rag-agent"},{"id":"AI Agents/Salesforce agent","title":"Salesforce agent","description":"What is the Salesforce agent?","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/salesforce-agent"},{"id":"AI Agents/SQL agent","title":"SQL agent","description":"The SQL agent in DataGOL is a tool designed to streamline the process of working with SQL by enabling users to interact with databases using natural language. It goes beyond simple query generation by also offering optimization and debugging capabilities for the created SQL.","permalink":"/datagol-knowlegde-base-v1/docs/AI Agents/sql-agent"}],"unlisted":false}}')}}]);